// CATOLICOSGPT — RECUPERACIÓN CONSERVADORA DE CONTENIDO
// Restaura únicamente catálogos públicos que quedaron vacíos.
// Nunca elimina contenido existente: los registros actuales siempre tienen prioridad.

const fs = require('fs');
const path = require('path');
const zlib = require('zlib');

const INFOGRAFIAS_GZIP_B64 =
'';

const INFOGRAFIAS_GZIP_B64_2 =
'' +
'' +
'' +
'';

const RECURSOS_PDF_GZIP_B64 = '';

function decodeCatalog(base64) {
  return JSON.parse(zlib.gunzipSync(Buffer.from(base64, 'base64')).toString('utf8'));
}

function safeRead(filePath) {
  try {
    const parsed = JSON.parse(fs.readFileSync(filePath, 'utf8'));
    return parsed && typeof parsed === 'object' ? parsed : {};
  } catch (_) {
    return {};
  }
}

function itemKey(item) {
  const v = item || {};
  return String(v.id || v.slug || v.url || v.titulo || v.title || '').trim().toLowerCase();
}

function mergeRecords(backupItems, currentItems) {
  const map = new Map();
  for (const item of Array.isArray(backupItems) ? backupItems : []) {
    const key = itemKey(item);
    if (key) map.set(key, item);
  }
  // El contenido actual gana siempre ante cualquier coincidencia.
  for (const item of Array.isArray(currentItems) ? currentItems : []) {
    const key = itemKey(item);
    if (key) map.set(key, item);
  }
  return [...map.values()];
}

function writeIfImproved(filename, listKey, backupCatalog, decorate) {
  const runtimeDir = process.env.DATA_DIR || path.join(__dirname, 'data');
  const runtimePath = path.join(runtimeDir, filename);
  const repoPath = path.join(__dirname, 'data', filename);
  try { fs.mkdirSync(runtimeDir, { recursive: true }); } catch (_) {}

  const runtime = safeRead(runtimePath);
  const fallback = safeRead(repoPath);
  const runtimeItems = Array.isArray(runtime[listKey]) ? runtime[listKey] : [];
  const fallbackItems = Array.isArray(fallback[listKey]) ? fallback[listKey] : [];
  const current = runtimeItems.length >= fallbackItems.length ? runtime : fallback;
  const currentItems = Array.isArray(current[listKey]) ? current[listKey] : [];
  const backupItems = Array.isArray(backupCatalog[listKey]) ? backupCatalog[listKey] : [];
  const mergedItems = mergeRecords(backupItems, currentItems);

  if (mergedItems.length <= currentItems.length) {
    console.log(`[Bootstrap Content] ${filename}: ${currentItems.length} registros, sin cambios.`);
    return currentItems.length;
  }

  let result = { ...backupCatalog, ...current, [listKey]: mergedItems };
  if (typeof decorate === 'function') result = decorate(result, mergedItems);
  const json = JSON.stringify(result, null, 2);

  try { fs.writeFileSync(runtimePath, json, 'utf8'); }
  catch (err) { console.warn(`[Bootstrap Content] No se pudo escribir ${runtimePath}:`, err.message); }

  if (repoPath !== runtimePath) {
    try { fs.writeFileSync(repoPath, json, 'utf8'); }
    catch (_) {}
  }

  console.log(`[Bootstrap Content] ${filename}: restaurados ${mergedItems.length} registros sin borrar contenido actual.`);
  return mergedItems.length;
}

function restoreBundledCatalogs() {
  try {
    const infografias = decodeCatalog(INFOGRAFIAS_GZIP_B64 + INFOGRAFIAS_GZIP_B64_2);
    writeIfImproved('infografias-catalog.json', 'infografias', infografias, (catalog, items) => ({
      ...catalog,
      total: items.length,
      categorias: [...new Set(items.map(i => i.categoria || i.tipo).filter(Boolean))]
    }));
  } catch (err) {
    console.error('[Bootstrap Content] Error restaurando infografías:', err.message);
  }

  try {
    const recursos = decodeCatalog(RECURSOS_PDF_GZIP_B64);
    writeIfImproved('recursos-pdf.json', 'recursos', recursos, (catalog) => ({
      ...catalog,
      updatedAt: catalog.updatedAt || new Date().toISOString()
    }));
  } catch (err) {
    console.error('[Bootstrap Content] Error restaurando PDFs:', err.message);
  }
}

module.exports = { restoreBundledCatalogs };
